import type { LucideIcon } from "lucide-react";
import { ArrowDownRight, ArrowUpRight } from "lucide-react";
import { cn } from "@/lib/cn";

type StatCardProps = {
  label: string;
  value?: string;
  delta?: number;
  icon?: LucideIcon;
  loading?: boolean;
};

export function StatCard({ label, value, delta, icon: Icon, loading = false }: StatCardProps) {
  const positive = typeof delta === "number" && delta >= 0;
  const DeltaIcon = positive ? ArrowUpRight : ArrowDownRight;
  return (
    <section className="rounded-card border border-border bg-surface p-5 shadow-card" aria-busy={loading || undefined}>
      <div className="flex items-start justify-between gap-4">
        <div className="min-w-0">
          <p className="truncate text-sm text-muted">{label}</p>
          {loading ? (
            <div className="mt-2 h-8 w-24 animate-pulse rounded-md bg-canvas motion-reduce:animate-none" aria-hidden="true" />
          ) : value ? (
            <p className="mt-1 text-2xl font-semibold tracking-tight">{value}</p>
          ) : (
            <p className="mt-1 text-sm text-muted">No data yet</p>
          )}
        </div>
        {Icon ? <Icon className="size-5 shrink-0 text-muted" aria-hidden="true" /> : null}
      </div>
      {typeof delta === "number" && !loading ? (
        <p className={cn("mt-3 inline-flex items-center gap-1 text-sm", positive ? "text-success" : "text-danger")}>
          <DeltaIcon className="size-4" aria-hidden="true" />
          <span>{Math.abs(delta)}%</span>
          <span className="text-muted">vs last month</span>
        </p>
      ) : null}
    </section>
  );
}
